<script setup>
import {computed,ref,watch,nextTick} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import {useIrrigation} from '../../data/runtime.js'
import {useListState} from '../../composables/useListState.js'
import {useDraftGuard} from '../../composables/useDraftGuard.js'
import BaseModal from '../../components/BaseModal.vue'
import StatusBadge from '../../components/StatusBadge.vue'
import FormField from '../../components/FormField.vue'
import {confirmAction,notify} from '../../composables/feedback.js'
import WorkOrderForm from '../alarms/WorkOrderForm.vue'
import {clone,kinds,dateText,futureInput,isoInput,failureText} from '../alarms/supportUi.js'
const r=useIrrigation(),route=useRoute(),router=useRouter(),state=useListState('maintenance',{filters:{assigneeId:'',kind:'DEVICE_REPAIR'}}),filters=ref({...state.filters}),modal=ref(false),creating=ref(false),snapshot=ref(null),draft=ref({}),note=ref(''),busy=ref(false),failure=ref(''),errors=ref({}),baseline=ref('')
const rows=computed(()=>(r.state.entities.WorkOrder??[]).filter(w=>Object.entries(state.filters).every(([k,v])=>!v||w[k]===v)).sort((a,b)=>Date.parse(a.dueAt)-Date.parse(b.dueAt))),lanes=[{title:'待接单',statuses:['ASSIGNED']},{title:'处理中',statuses:['IN_PROGRESS','RETURNED']},{title:'待验收',statuses:['PENDING_ACCEPTANCE']},{title:'已完成',statuses:['COMPLETED']}],people=computed(()=>(r.state.entities.User??[]).filter(u=>u.role==='TECHNICIAN'))
const dirty=computed(()=>modal.value&&(creating.value?JSON.stringify(draft.value)!==baseline.value:!!note.value)),guard=useDraftGuard(()=>dirty.value),get=(kind,id)=>r.getIndex().byId[kind]?.get(id),alarm=computed(()=>get('Alarm',snapshot.value?.alarmId))
function open(w){creating.value=!w;snapshot.value=w?clone(w):null;draft.value={kind:'DEVICE_REPAIR',assigneeId:'',zoneId:'',deviceId:'',dueAt:futureInput(),note:''};note.value='';failure.value='';errors.value={};baseline.value=JSON.stringify(draft.value);state.selectedId=w?.workOrderId??null;modal.value=true}
watch(()=>route.query.selected,id=>{if(id){const w=get('WorkOrder',id);if(w)open(w);else failure.value='工单不存在或无权查看，请调整筛选。'}},{immediate:true})
async function close(){if(busy.value)return;if(!dirty.value||await confirmAction({title:'放弃未保存内容',message:'当前工单内容尚未保存，确认放弃？',confirmText:'放弃'}))modal.value=false;else{modal.value=false;await nextTick();modal.value=true}}
function allowed(action){const w=snapshot.value;if(!w||!r.can(action,w))return false;if(action==='WORKORDER_ACCEPT')return ['ASSIGNED','RETURNED'].includes(w.status);if(action==='WORKORDER_SUBMIT')return ['IN_PROGRESS','RETURNED'].includes(w.status);if(action==='WORKORDER_APPROVE')return w.status==='PENDING_ACCEPTANCE'&&(!w.alarmId||alarm.value?.recovery==='RECOVERED');return w.status==='PENDING_ACCEPTANCE'}
async function submit(action){busy.value=true;failure.value='';errors.value={};try{await r.commit(action,creating.value?{...draft.value,dueAt:isoInput(draft.value.dueAt)}:{workOrderId:snapshot.value.workOrderId,note:note.value,resultNote:note.value},{expectedVersion:snapshot.value?.version,clientRequestId:crypto.randomUUID()});notify('工单已保存');baseline.value=JSON.stringify(draft.value);note.value='';modal.value=false;guard.markClean()}catch(e){failure.value=failureText(e);errors.value=e.fieldErrors??{}}finally{busy.value=false}}
</script>
<template><div class="page-stack maintenance-page"><form class="filters maintenance-filters" @submit.prevent="state.filters={...filters}"><label class="filter-field">责任人<select v-model="filters.assigneeId"><option value="">全部</option><option v-for="u in people" :key="u.userId" :value="u.userId">{{u.name}}</option></select></label><label class="filter-field">类型<select v-model="filters.kind"><option value="">全部</option><option v-for="(v,k) in kinds" :key="k" :value="k">{{v}}</option></select></label><div class="filter-spacer"/><button class="btn btn-primary">查询</button><button type="button" class="btn" :disabled="!r.can('WORKORDER_CREATE')" @click="open()">新建工单</button></form><p v-if="failure&&!modal" role="alert" class="error-text">{{failure}}</p><div class="work-lanes"><section v-for="(lane,i) in lanes" :key="lane.title" class="work-lane" :class="'lane-'+i"><h2>{{lane.title}} <strong>{{rows.filter(w=>lane.statuses.includes(w.status)).length}}</strong></h2><div class="lane-cards"><button v-for="w in rows.filter(w=>lane.statuses.includes(w.status))" :key="w.workOrderId" class="work-card" @click="open(w)"><header><strong>{{w.workOrderId}}</strong><StatusBadge :status="w.status"/></header><dl><dt>分区</dt><dd>{{get('IrrigationZone',w.zoneId)?.name||'—'}}</dd><dt>责任人</dt><dd>{{get('User',w.assigneeId)?.name||'—'}}</dd><dt>期限</dt><dd>{{dateText(w.dueAt,true)}}</dd></dl></button><p v-if="!rows.some(w=>lane.statuses.includes(w.status))" class="empty-state">暂无工单</p></div></section></div><div class="muted">共{{rows.length}}条维护工单，责任人{{state.filters.assigneeId?get('User',state.filters.assigneeId)?.name:'全部'}}</div><BaseModal :model-value="modal" :title="creating?'新建工单':'维护工单详情'" :busy="busy" width="740px" @update:model-value="close"><WorkOrderForm v-if="creating" :draft="draft" :errors="errors" :busy="busy"/><template v-else-if="snapshot"><div class="work-modal-head"><strong>{{snapshot.workOrderId}}</strong><StatusBadge :status="snapshot.status"/></div><dl class="data-pairs"><dt>工单类型</dt><dd>{{kinds[snapshot.kind]||snapshot.kind}}</dd><dt>分区</dt><dd>{{get('IrrigationZone',snapshot.zoneId)?.name||'—'}}</dd><dt>责任人</dt><dd>{{get('User',snapshot.assigneeId)?.name||'—'}}</dd><dt>期限</dt><dd>{{dateText(snapshot.dueAt)}}</dd><dt>设备</dt><dd><button v-if="snapshot.deviceId" class="btn-link" @click="router.push('/devices/'+snapshot.deviceId)">{{get('Device',snapshot.deviceId)?.name||snapshot.deviceId}}</button><span v-else>—</span></dd><dt>关联告警</dt><dd><button v-if="snapshot.alarmId" class="btn-link" @click="router.push({path:'/alarms',query:{selected:snapshot.alarmId}})">{{snapshot.alarmId}} · {{alarm?.recovery==='RECOVERED'?'已恢复':'未恢复'}}</button><span v-else>无关联告警</span></dd><dt>工单说明</dt><dd>{{snapshot.requestNote||'—'}}</dd><dt>处理结果</dt><dd>{{snapshot.resultNote||'尚未提交'}}</dd><dt>验收记录</dt><dd>{{snapshot.reviewNote||'—'}}</dd><dt>接单时间</dt><dd>{{dateText(snapshot.startedAt)}}</dd><dt>完成时间</dt><dd>{{dateText(snapshot.completedAt)}}</dd></dl><FormField v-if="['WORKORDER_ACCEPT','WORKORDER_SUBMIT','WORKORDER_APPROVE','WORKORDER_RETURN'].some(allowed)" label="处理结果 / 验收说明 / 退回理由" :error="errors.resultNote||errors.note"><textarea v-model="note" :disabled="busy" rows="4" placeholder="提交处理结果至少12字；退回理由至少6字"/></FormField><p v-if="snapshot.status==='PENDING_ACCEPTANCE'&&alarm&&alarm.recovery!=='RECOVERED'" class="error-text">关联故障未恢复，不能通过验收。</p></template><p v-if="failure" role="alert" class="error-text">{{failure}}</p><template #footer><button class="btn" :disabled="busy" @click="close">取消</button><button v-if="creating" class="btn btn-primary" :disabled="busy||!r.can('WORKORDER_CREATE')" @click="submit('WORKORDER_CREATE')">创建工单</button><template v-else><button v-for="(title,action) in {WORKORDER_ACCEPT:'接单',WORKORDER_SUBMIT:'提交结果',WORKORDER_APPROVE:'验收通过',WORKORDER_RETURN:'退回'}" v-show="allowed(action)" :key="action" class="btn" :class="{'btn-primary':action!=='WORKORDER_RETURN'}" :disabled="busy" @click="submit(action)">{{title}}</button></template></template></BaseModal></div></template>
<style scoped>.maintenance-page{gap:18px;padding:4px 3px}.maintenance-filters{padding:0 0 6px;gap:26px;height:68px}.maintenance-filters .filter-field{flex:0;flex-direction:row;align-items:center;gap:15px;white-space:nowrap}.maintenance-filters select{width:215px;height:43px}.maintenance-filters .btn{min-width:112px;height:44px}.filter-spacer{flex:1}.work-lanes{display:grid;grid-template-columns:1.03fr 1fr 1fr 1fr;gap:8px;height:798px}.work-lane{border-radius:10px;background:#e3f3ff;padding:13px 10px 10px;min-width:0;display:flex;flex-direction:column}.lane-1,.lane-3{background:#e4f6ec}.lane-2{background:#fff3dd}.work-lane h2{font-size:22px;color:#064c79;margin:4px 12px 17px}.lane-1 h2,.lane-3 h2,.lane-2 h2{color:#005b46}.work-lane h2 strong{color:#007758;margin-left:12px}.lane-cards{overflow:auto;min-height:0;display:flex;flex-direction:column;gap:10px}.work-card{background:#fff;border:0;border-radius:10px;text-align:left;padding:11px 16px 13px;min-height:135px;width:100%;cursor:pointer;color:#20342f}.work-card:hover{outline:1px solid #87bca9}.work-card header{display:flex;justify-content:space-between;align-items:center;gap:7px;margin-bottom:11px}.work-card header strong{font-size:16px;white-space:nowrap}.work-card dl{display:grid;grid-template-columns:67px 1fr;margin:0;gap:5px;font-size:15px}.work-card dt{color:#617a73}.work-card dd{margin:0;white-space:nowrap}.work-modal-head{display:flex;justify-content:space-between;margin-bottom:18px}
</style>
